source('diagnostics/revision20261022/score_lib.R');source('code/lib/central.R')
suppressPackageStartupMessages(library(ggplot2))
root<-rev_root();out<-file.path(root,'reports');fig<-file.path(out,'figures');dir.create(fig,recursive=TRUE,showWarnings=FALSE)
variants<-c('h24','h48','onset','support_only','low_flow','carry0','carry12','raw_support');meta<-list();effects<-list();performance<-list();local<-list();profiles<-list()
for(v in variants){
 r<-file.path(root,'sensitivities',v)
 for(version in c('full','loo_UCMC','loo_NU','loo_RUSH')){
 m<-jsonlite::fromJSON(file.path(r,'coordinator',version,'frozen_manifest.json'))
 meta[[paste(v,version)]]<-tibble::tibble(analysis=v,version=version,k=m$k,consensus_id=m$consensus_id,window=m$specification$window)
 }
 z<-readr::read_csv(file.path(r,'coordinator/full/outcomes/pooled_associations.csv'),show_col_types=FALSE);effects[[v]]<-z |> dplyr::mutate(analysis=v)
 pr<-readr::read_csv(file.path(r,'coordinator/full/prototypes.csv'),show_col_types=FALSE);profiles[[v]]<-pr |> dplyr::filter(domain=='support') |> dplyr::group_by(phenotype,state) |> dplyr::summarise(probability=mean(probability),.groups='drop') |> dplyr::mutate(analysis=v)
 for(s in c('UCMC','NU','RUSH')){
 mm<-jsonlite::fromJSON(file.path(r,'sites',s,'local/discovery_audit.json'));si<-readr::read_csv(file.path(r,'sites',s,'export/discovery/silhouette.csv'),show_col_types=FALSE)
 local[[paste(v,s)]]<-tibble::tibble(analysis=v,site=s,n=mm$n,local_k=mm$k,silhouette=max(si$silhouette))
 z<-readr::read_csv(file.path(r,'sites',s,'export/transport/metrics.csv'),show_col_types=FALSE);performance[[paste(v,s)]]<-z |> dplyr::mutate(analysis=v)
 }
}
for(pair in list(list(meta,'sensitivity_consensus.csv'),list(effects,'sensitivity_pooled_associations.csv'),list(performance,'sensitivity_transport.csv'),list(local,'sensitivity_cohorts_and_local_k.csv'),list(profiles,'sensitivity_support_profiles.csv')))fed_write(dplyr::bind_rows(pair[[1]]),file.path(out,'tables',pair[[2]]))
# Plots consume coordinator/approved aggregate tables only.
metrics<-readr::read_csv(file.path(out,'tables/score_transport_metrics.csv'),show_col_types=FALSE)
z<-metrics |> dplyr::filter(endpoint=='death_or_hospice',metric=='auc',model%in%c('sofa_only','sofa','phenotype','sofa_summaries','sofa_summaries_phenotype'))
labels<-c(sofa_only='Modified SOFA alone',sofa='Baseline + modified SOFA',phenotype='Baseline + phenotype',sofa_summaries='Baseline + modified SOFA + summaries',sofa_summaries_phenotype='Baseline + modified SOFA + summaries + phenotype')
z$label<-factor(labels[z$model],levels=rev(unname(labels)));z$cohort<-factor(z$cohort,levels=c('measured_sofa','missing_domain_zero_sensitivity'),labels=c('Complete measured components','Missing-domain-zero sensitivity'))
g<-ggplot(z,aes(estimate,label,color=site))+geom_point(position=position_dodge(width=.65))+geom_errorbar(aes(xmin=conf_low,xmax=conf_high),orientation='y',width=.2,position=position_dodge(width=.65))+facet_wrap(~cohort,ncol=1)+scale_x_continuous(limits=c(.35,1))+labs(x='Held-out-site AUC (95% patient-bootstrap interval)',y=NULL,title='Direct comparison with modified SOFA',subtitle='28-day hospital death/hospice after ICU +72h; identical patients across models within each panel',caption='SOFA uses creatinine-only renal scoring. Missing-domain-zero is an explicitly incomplete-score sensitivity. APACHE II/IV unavailable.')+theme_minimal(base_size=11)+theme(legend.position='bottom',plot.caption=element_text(hjust=0))
ggsave(file.path(fig,'sofa_direct_comparison.png'),g,width=12,height=8.5,dpi=180)
inc<-readr::read_csv(file.path(out,'tables/score_paired_increments.csv'),show_col_types=FALSE) |> dplyr::filter(endpoint=='death_or_hospice',metric=='auc',comparison=='phenotype_beyond_sofa')
inc$cohort<-factor(inc$cohort,levels=c('measured_sofa','missing_domain_zero_sensitivity'),labels=c('Complete measured components','Missing-domain-zero sensitivity'))
g<-ggplot(inc,aes(estimate,site,color=cohort))+geom_vline(xintercept=0,linetype=2,color='grey50')+geom_point(position=position_dodge(width=.5))+geom_errorbar(aes(xmin=conf_low,xmax=conf_high),orientation='y',position=position_dodge(width=.5),width=.2)+labs(x='AUC change when adding phenotype to baseline + modified SOFA + summaries',y=NULL,title='Increment beyond severity and simple respiratory summaries',caption='Paired patient-bootstrap intervals conditional on the frozen two-site learner. Summaries include support at hour 72.')+theme_minimal(base_size=11)+theme(legend.position='bottom',plot.caption=element_text(hjust=0))
ggsave(file.path(fig,'increment_beyond_sofa_and_summaries.png'),g,width=12,height=4.5,dpi=180)
dc<-readr::read_csv(file.path(out,'tables/score_decision_curves.csv'),show_col_types=FALSE) |> dplyr::filter(endpoint=='death_or_hospice',cohort=='measured_sofa',model%in%names(labels))
g<-ggplot(dc,aes(threshold,net_benefit,color=model))+geom_line()+geom_hline(yintercept=0,color='grey50')+geom_line(aes(y=treat_all),color='black',linetype=2)+facet_wrap(~site)+scale_color_discrete(labels=labels)+coord_cartesian(ylim=c(-.2,.65))+labs(x='Risk threshold',y='Net benefit',title='Exploratory decision curves: measured-component SOFA cohort',caption='Dashed: act on all; horizontal zero: act on none. Curves assess a hypothetical threshold decision, not treatment benefit.')+theme_minimal(base_size=10)+theme(legend.position='bottom',plot.caption=element_text(hjust=0))
ggsave(file.path(fig,'decision_curves_measured_sofa.png'),g,width=13,height=5,dpi=180)
cl<-readr::read_csv(file.path(out,'tables/continuous_denominators.csv'),show_col_types=FALSE) |> dplyr::filter(variable%in%c('hypox_fraction','hyper_fraction','mixed_fraction'))
cl$evidence<-factor(cl$variable,levels=c('hypox_fraction','hyper_fraction','mixed_fraction'),labels=c('Hypoxemic evidence','Hypercapnic/acidemic evidence','Simultaneous mixed evidence'))
g<-ggplot(cl,aes(phenotype,100*mean,fill=evidence))+geom_col(position='dodge')+facet_wrap(~site)+labs(x='Frozen shared phenotype (I = insufficient/ambiguous)',y='Mean percentage of 72 hours',title='ARF evidence within the shared respiratory phenotypes',caption='Mixed hours also contribute to both channel totals. Unknown physiology is not negative evidence. Small observed partitions masked.')+theme_minimal(base_size=10)+theme(legend.position='bottom',plot.caption=element_text(hjust=0))
ggsave(file.path(fig,'arf_contribution.png'),g,width=12,height=5,dpi=180)
tr<-dplyr::bind_rows(performance) |> dplyr::filter(metric=='auc',model=='plus_phenotype',analysis%in%c('h24','h48'))
g<-ggplot(tr,aes(analysis,estimate,color=site))+geom_point(position=position_dodge(width=.45))+geom_errorbar(aes(ymin=conf_low,ymax=conf_high),position=position_dodge(width=.45),width=.2)+scale_x_discrete(labels=c(h24='24 hours',h48='48 hours'))+labs(x='Landmark',y='Held-out-site AUC',title='Earlier landmark prediction',caption='Separate eligible cohorts and separately learned phenotypes; estimates are not a paired 24-vs-48-vs-72-hour comparison.')+theme_minimal(base_size=11)+theme(legend.position='bottom',plot.caption=element_text(hjust=0))
ggsave(file.path(fig,'earlier_landmark_auc.png'),g,width=9,height=5,dpi=180)
